/**
 * CRUD broadcasts integration.
 *
 * The Crud package publishes `crud.model.changed` on the private channel
 * `channel.crud-events.models.<kebab model basename>`. Keep this module as
 * the sole Echo listener: DataTables instances sharing a model share one
 * subscription and are registered/unregistered through DataTables lifecycle
 * events.
 */
(function () {
    const subscriptions = {};
    const refreshTableSubscriptions = {};
    const createdStates = {};
    const refreshDelay = 100;
    const browserTabId = createBrowserTabId();

    window.__ibDatatableModelBroadcasts = subscriptions;
    window.__ibDatatableRefreshTableBroadcasts = refreshTableSubscriptions;
    window.ibGetDatatableBrowserTabId = function () {
        return browserTabId;
    };

    function createBrowserTabId() {
        if (window.crypto && typeof window.crypto.randomUUID === 'function')
            return window.crypto.randomUUID();

        return 'ibdt-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
    }

    function logCrudEvent(payload) {
        if (typeof window.addFooterLog !== 'function')
            return;

        try {
            window.addFooterLog(
                payload.text || ('CRUD event: ' + (payload.action || 'changed')),
                {
                    source: 'datatables',
                    event: 'crud.model.changed',
                    model: payload.model,
                    key: payload.key,
                    action: payload.action,
                }
            );
        } catch (error) {
            // A footer logger must never prevent the table refresh.
        }
    }

    function getDatatable(table) {
        if (!table || !$.fn.dataTable.isDataTable(table))
            return null;

        return $(table).DataTable();
    }

    function reloadTable(datatable) {
        if (datatable.ajax && typeof datatable.ajax.reload === 'function') {
            datatable.ajax.reload(null, false);
            return;
        }

        if (typeof datatable.draw === 'function')
            datatable.draw(false);
    }

    function getCreatedState(table) {
        if (!createdStates[table.id]) {
            createdStates[table.id] = {
                completedKeys: new Set(),
                inFlightKeys: new Set(),
                serverReloadTimeout: null,
            };
        }

        return createdStates[table.id];
    }

    function isServerSide(datatable) {
        const settings = datatable.settings && datatable.settings()[0];

        return !!(settings && (
            settings.serverSide
            || (settings.oFeatures && settings.oFeatures.bServerSide)
        ));
    }

    function scheduleServerReload(table, datatable) {
        const state = getCreatedState(table);

        if (state.serverReloadTimeout)
            clearTimeout(state.serverReloadTimeout);

        state.serverReloadTimeout = setTimeout(function () {
            state.serverReloadTimeout = null;
            reloadTable(datatable);
        }, refreshDelay);
    }

    function getWindowFunction(name) {
        if (!name)
            return null;

        return name
            .replace(/^window\./, '')
            .split('.')
            .reduce(function (value, property) {
                return value && value[property];
            }, window);
    }

    function getCreatedFetchRequest(table, datatable, payload) {
        const hookName = table.getAttribute('data-model-broadcast-created-fetch-hook');
        const hook = getWindowFunction(hookName);

        if (hookName) {
            if (typeof hook !== 'function')
                throw new Error('Configured created-row fetch hook is not a function.');

            return hook(table, payload.key, payload, datatable);
        }

        const url = table.getAttribute('data-model-broadcast-created-fetch-url')
            || (
                datatable.ajax
                && typeof datatable.ajax.url === 'function'
                && datatable.ajax.url()
            );

        if (!url)
            return null;

        return {
            data: { rowId: payload.key },
            dataType: 'json',
            type: 'GET',
            url: url,
        };
    }

    function requestCreatedRow(table, datatable, payload) {
        const request = getCreatedFetchRequest(table, datatable, payload);

        if (!request)
            return Promise.reject(new Error('No created-row fetch request is configured.'));

        if (typeof request.then === 'function')
            return Promise.resolve(request);

        if (typeof request === 'string') {
            return Promise.resolve($.ajax({
                data: { rowId: payload.key },
                dataType: 'json',
                type: 'GET',
                url: request,
            }));
        }

        return Promise.resolve($.ajax(request));
    }

    function extractCreatedRow(response) {
        if (!response || !Array.isArray(response.data) || !response.data.length)
            return null;

        const row = response.data[0];

        if (!Array.isArray(row) && (!row || typeof row !== 'object'))
            return null;

        return row;
    }

    function tableHasKey(datatable, key) {
        if (!datatable.rows || typeof datatable.rows !== 'function')
            return false;

        let found = false;

        datatable.rows().every(function () {
            if (found)
                return;

            if (typeof this.id === 'function') {
                const rowId = this.id();

                if (rowId !== undefined && rowId !== null && String(rowId) === String(key))
                    found = true;
            }
        });

        return found;
    }

    function addCreatedRow(table, datatable, payload) {
        const state = getCreatedState(table);
        const key = String(payload.key);

        if (isServerSide(datatable)) {
            scheduleServerReload(table, datatable);
            return;
        }

        if (
            state.inFlightKeys.has(key)
            || state.completedKeys.has(key)
            || tableHasKey(datatable, payload.key)
        ) {
            state.completedKeys.add(key);
            return;
        }

        state.inFlightKeys.add(key);

        let request;

        try {
            request = requestCreatedRow(table, datatable, payload);
        } catch (error) {
            state.inFlightKeys.delete(key);
            reloadTable(datatable);
            return;
        }

        request
            .then(function (response) {
                const row = extractCreatedRow(response);

                if (!row)
                    throw new Error('Invalid created-row response.');

                // Do not add an already-present record if the table changed
                // while its canonical row was being fetched.
                if (state.completedKeys.has(key) || tableHasKey(datatable, payload.key))
                    return;

                const addedRow = datatable.row.add(row);

                addedRow.draw(false);

                if (typeof addedRow.node === 'function') {
                    const rowNode = addedRow.node();

                    if (rowNode)
                        applyTemporaryAnimation(rowNode, 'ib-datatable-row-broadcast-created', 1800);
                }

                state.completedKeys.add(key);
            })
            .catch(function () {
                reloadTable(datatable);
            })
            .then(function () {
                state.inFlightKeys.delete(key);
            });
    }

    function removeRow(datatable, table, key) {
        const row = datatable.rows().nodes().toArray().find(function (node) {
            return String(node.id) === String(key) && table.contains(node);
        });

        if (!row)
            return false;

        datatable.row(row).remove().draw(false);

        return true;
    }

    function refreshUpdatedRows(table, datatable, keys) {
        if (!keys.length || typeof window.reloadTableRows !== 'function') {
            reloadTable(datatable);
            return;
        }

        window.reloadTableRows('#' + table.id, keys, null, function (refreshedDatatable, refreshedRows) {
            highlightUpdatedRows(refreshedDatatable, refreshedRows);
        });
    }

    function applyTemporaryAnimation(element, className, duration) {
        element.classList.remove(className);

        // Force the browser to restart the animation when the same element is
        // refreshed more than once before the previous flash has finished.
        void element.offsetWidth;

        element.classList.add(className);
        window.setTimeout(function () {
            element.classList.remove(className);
        }, duration);
    }

    function highlightUpdatedRows(datatable, refreshedRows) {
        if (!refreshedRows.length)
            return;

        const refreshedRowsByKey = new Map(refreshedRows.map(function (refreshedRow) {
            return [String(refreshedRow.rowId), refreshedRow];
        }));
        const rows = datatable.rows().nodes().toArray().filter(function (node) {
            return node && refreshedRowsByKey.has(String(node.id));
        });

        rows.forEach(function (row) {
            const refreshedRow = refreshedRowsByKey.get(String(row.id));

            applyTemporaryAnimation(row, 'ib-datatable-row-broadcast-updated', 1600);

            refreshedRow.changedColumnIndexes.forEach(function (columnIndex) {
                const cell = datatable.cell(row, columnIndex).node();

                if (cell)
                    applyTemporaryAnimation(cell, 'ib-datatable-cell-broadcast-updated', 2200);
            });
        });
    }

    function hasKey(payload) {
        return payload.key !== undefined && payload.key !== null && payload.key !== '';
    }

    function wasTriggeredByTable(table, payload) {
        const origin = payload && payload.origin;

        return !!(
            origin
            && origin.browserTabId === browserTabId
            && origin.tableId === table.id
        );
    }

    function processTableEvents(table, events) {
        const datatable = getDatatable(table);

        if (!datatable)
            return;

        const modelClass = table.getAttribute('data-model-broadcast-model');
        const relevantEvents = events.filter(function (payload) {
            return payload
                && payload.model === modelClass
                && !wasTriggeredByTable(table, payload);
        });

        if (!relevantEvents.length)
            return;

        const createdEvents = relevantEvents.filter(function (payload) {
            return payload.action === 'created';
        });

        createdEvents.forEach(function (payload) {
            if (!hasKey(payload)) {
                reloadTable(datatable);
                return;
            }

            addCreatedRow(table, datatable, payload);
        });

        const otherEvents = relevantEvents.filter(function (payload) {
            return payload.action !== 'created';
        });

        if (!otherEvents.length)
            return;

        if (otherEvents.some(function (payload) {
            return !hasKey(payload);
        })) {
            reloadTable(datatable);
            return;
        }

        const removed = otherEvents.filter(function (payload) {
            return ['deleted', 'forceDeleted', 'archived'].includes(payload.action);
        });

        if (removed.length) {
            const state = getCreatedState(table);

            removed.forEach(function (payload) {
                state.completedKeys.delete(String(payload.key));
            });
        }

        const mustReload = removed.some(function (payload) {
            return !removeRow(datatable, table, payload.key);
        });

        if (mustReload) {
            reloadTable(datatable);
            return;
        }

        const removedKeys = new Set(removed.map(function (payload) {
            return String(payload.key);
        }));

        const updatedKeys = relevantEvents
            .filter(function (payload) {
                return payload.action === 'updated' && !removedKeys.has(String(payload.key));
            })
            .map(function (payload) { return payload.key; });

        if (updatedKeys.length)
            refreshUpdatedRows(table, datatable, updatedKeys);

        if (otherEvents.some(function (payload) {
            return !['updated', 'deleted', 'forceDeleted', 'archived'].includes(payload.action);
        }))
            reloadTable(datatable);
    }

    function flush(subscription) {
        subscription.timeout = null;

        const events = subscription.pendingEvents.splice(0);

        subscription.tableIds.forEach(function (tableId) {
            const table = document.getElementById(tableId);

            if (!table) {
                subscription.tableIds.delete(tableId);
                return;
            }

            processTableEvents(table, events);
        });
    }

    function schedule(subscription, payload) {
        if (!payload || !payload.model)
            return;

        logCrudEvent(payload);
        subscription.pendingEvents.push(payload);

        if (!subscription.timeout)
            subscription.timeout = setTimeout(function () {
                flush(subscription);
            }, refreshDelay);
    }

    function subscribe(channelName) {
        if (subscriptions[channelName])
            return subscriptions[channelName];

        if (!window.Echo || typeof window.Echo.private !== 'function')
            return null;

        const subscription = subscriptions[channelName] = {
            tableIds: new Set(),
            pendingEvents: [],
            timeout: null,
        };

        window.Echo
            .private(channelName)
            .listen('.crud.model.changed', function (payload) {
                schedule(subscription, payload);
            });

        return subscription;
    }

    function subscribeRefreshTable(channelName) {
        if (refreshTableSubscriptions[channelName])
            return refreshTableSubscriptions[channelName];

        if (!window.Echo || typeof window.Echo.private !== 'function')
            return null;

        const subscription = refreshTableSubscriptions[channelName] = {
            tableIds: new Set(),
        };

        window.Echo
            .private(channelName)
            .listen('.refreshTable', function () {
                subscription.tableIds.forEach(function (tableId) {
                    const table = document.getElementById(tableId);

                    if (!table) {
                        subscription.tableIds.delete(tableId);
                        return;
                    }

                    const datatable = getDatatable(table);

                    if (datatable)
                        reloadTable(datatable);
                });
            });

        return subscription;
    }

    $(document).on('init.dt', function (event, settings) {
        const table = settings.nTable;
        const channelName = table.getAttribute('data-model-broadcast-channel');

        const refreshTableChannelName = table.getAttribute('data-refresh-table-broadcast-channel');

        if (refreshTableChannelName) {
            const refreshTableSubscription = subscribeRefreshTable(refreshTableChannelName);

            if (refreshTableSubscription)
                refreshTableSubscription.tableIds.add(table.id);
        }

        if (!channelName)
            return;

        const subscription = subscribe(channelName);

        if (subscription)
            subscription.tableIds.add(table.id);
    });

    $(document).on('destroy.dt', function (event, settings) {
        const tableId = settings.nTable && settings.nTable.id;

        if (!tableId)
            return;

        Object.keys(subscriptions).forEach(function (channelName) {
            subscriptions[channelName].tableIds.delete(tableId);
        });

        Object.keys(refreshTableSubscriptions).forEach(function (channelName) {
            refreshTableSubscriptions[channelName].tableIds.delete(tableId);
        });

        if (createdStates[tableId] && createdStates[tableId].serverReloadTimeout)
            clearTimeout(createdStates[tableId].serverReloadTimeout);

        delete createdStates[tableId];
    });
})();
